shaders.source:
struct Uniforms {
  mvp : mat4x4<f32>,
  normalMatrix : mat3x3<f32>,
  lacquerBlack : vec3<f32>,
  cinnabar : vec3<f32>,
  goldLeaf : vec3<f32>,
};
@group(0) @binding(0) var<uniform> u : Uniforms;

struct VertexInput {
  @location(0) position : vec3<f32>,
  @location(1) normal : vec3<f32>,
  @location(2) uv : vec2<f32>,
};

struct VertexOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) vNormal : vec3<f32>,
  @location(1) vUv : vec2<f32>,
};

@vertex
fn vertexMain(in : VertexInput) -> VertexOutput {
  var out : VertexOutput;
  out.vNormal = in.normal;
  out.vUv = in.uv;
  out.position = (u.mvp * vec4<f32>(in.position, 1.0));
  return out;
}

@fragment
fn fragmentMain(in : VertexOutput) -> @location(0) vec4<f32> {
  let n = normalize(in.vNormal);
  let cloudA = sin(((in.vUv.x * 31.0) + (sin((in.vUv.y * 9.0)) * 3.0)));
  let cloudB = sin(((in.vUv.y * 47.0) + (sin((in.vUv.x * 13.0)) * 2.0)));
  let cloud = clamp((((cloudA + cloudB) * 0.18) + 0.34), 0.0, 1.0);
  let flake = smoothstep(0.985, 0.94, abs((sin((in.vUv.x * 173.0)) * sin((in.vUv.y * 149.0)))));
  let body = mix(u.lacquerBlack.rgb, u.cinnabar.rgb, cloud);
  let gilded = mix(body, u.goldLeaf.rgb, (flake * 0.38));
  let clear = (pow((1.0 - abs(n.z)), 4.0) * 0.16);
  return vec4<f32>((gilded + vec3<f32>(clear, clear, clear)), 1.0);
}

shaders.vertex:
#version 300 es
in vec3 position;
in vec3 normal;
in vec2 uv;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 lacquerBlack;
uniform vec3 cinnabar;
uniform vec3 goldLeaf;
out vec3 vNormal;
out vec2 vUv;

void main() {
  vNormal = normal;
  vUv = uv;
  gl_Position = (mvp * vec4(position, 1.0));
}

shaders.fragment:
#version 300 es
precision highp float;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 lacquerBlack;
uniform vec3 cinnabar;
uniform vec3 goldLeaf;
in vec3 vNormal;
in vec2 vUv;
out vec4 fragColor;

void main() {
  vec3 n = normalize(vNormal);
  float cloudA = sin(((vUv.x * 31.0) + (sin((vUv.y * 9.0)) * 3.0)));
  float cloudB = sin(((vUv.y * 47.0) + (sin((vUv.x * 13.0)) * 2.0)));
  float cloud = clamp((((cloudA + cloudB) * 0.18) + 0.34), 0.0, 1.0);
  float flake = smoothstep(0.985, 0.94, abs((sin((vUv.x * 173.0)) * sin((vUv.y * 149.0)))));
  vec3 body = mix(lacquerBlack.rgb, cinnabar.rgb, cloud);
  vec3 gilded = mix(body, goldLeaf.rgb, (flake * 0.38));
  float clear = (pow((1.0 - abs(n.z)), 4.0) * 0.16);
  fragColor = vec4((gilded + vec3(clear, clear, clear)), 1.0);
}
